// Vercel Routing Middleware: Markdown content negotiation.
//
// Static files win over vercel.json `rewrites`, so a `has: accept` rewrite can
// never override "/" or an existing .html file. Middleware runs first.
// Requests whose Accept header asks for text/markdown get the .md twin
// (built by scripts/build_markdown.py); everything else is untouched.

// BEGIN PAGES (generated by scripts/build_markdown.py; do not edit)
const PAGES = ["about", "bots/agent-council", "bots/bot-skill-auditor", "bots/company-deep-dive", "bots/dependency-vuln-triage", "bots/domain-infra-hygiene", "bots/fai-results-reconciler", "bots/mcp-config-auditor", "bots/mill-cert-matcher", "bots/print-farm-ops", "bots/rfq-flowdown-triage", "bots/robotics-telemetry-inspector", "bots/sec-patent-watchdog", "bots/sec-supply-chain-mapper", "bots/social-hub-publisher", "bots/web-text-extractor", "contact", "index", "privacy"];
// END PAGES

const SITE = "https://botappstore.com";
const KNOWN = new Set(PAGES);

export const config = { matcher: "/:path*" };

export function wantsMarkdown(accept) {
  return String(accept || "")
    .split(",")
    .some((part) => {
      const [type, ...params] = part.trim().toLowerCase().split(";");
      if (type.trim() !== "text/markdown") return false;
      const q = params.map((p) => p.trim()).find((p) => p.startsWith("q="));
      return !q || parseFloat(q.slice(2)) > 0;
    });
}

// "/bots/x.html" -> "bots/x"; "/" -> "index"; null for non-page paths
// (assets, /runtime/*, files with another extension).
export function pageKey(pathname) {
  let p = pathname.replace(/\/+$/, "").replace(/^\/+/, "");
  if (p === "runtime" || p.startsWith("runtime/")) return null;
  p = p.replace(/\.html$/, "");
  if (p === "") return "index";
  if (/\.[^/]*$/.test(p)) return null;
  return p;
}

const next = () => new Response(null, { headers: { "x-middleware-next": "1" } });

const rewrite = (dest, headers) =>
  new Response(null, { headers: { ...headers, "x-middleware-rewrite": String(dest) } });

export default function middleware(request) {
  const url = new URL(request.url);
  if (request.method !== "GET" && request.method !== "HEAD") return next();
  if (!wantsMarkdown(request.headers.get("accept"))) return next();
  const key = pageKey(url.pathname);
  if (key === null) return next();
  const headers = { "Content-Type": "text/markdown; charset=utf-8", Vary: "Accept" };
  if (KNOWN.has(key)) return rewrite(new URL(`/${key}.md`, url), headers);
  const body =
    "# Not found\n\n" +
    `No page exists at \`${url.pathname.replace(/[`\r\n]/g, "")}\`.\n\n` +
    `- Agent index: ${SITE}/llms.txt\n- Catalog (JSON): ${SITE}/catalog.json\n`;
  return new Response(request.method === "HEAD" ? null : body, { status: 404, headers });
}
